-- Mundo Viajero — migración de M12 fase 2: el catálogo (paquetes, destinos, experiencias, eventos) en Supabase,
-- editable desde el panel /admin. Antes vivía solo en `data/*.ts`; esos archivos quedan como semilla y como
-- respaldo del sitio si la base no responde (ver lib/catalog/read.ts).
--
-- Cómo ejecutarla: Supabase → SQL Editor → New query → pegar este archivo COMPLETO → Run. Requiere haber corrido
-- antes `supabase/schema.sql` (usa su función `travel_quotes_set_updated_at`).
-- Es segura de repetir: la tabla y las políticas usan "if not exists"/"drop ... if exists", y la semilla usa
-- "on conflict do nothing" (no pisa lo que ya se haya editado en el panel).

begin;

-- ============================================================================
-- 1. Una sola tabla para los cuatro tipos. Las columnas fijas son las que la base necesita para filtrar y
--    ordenar; el contenido de cada elemento va en `data` (JSONB) con la misma forma que los tipos de
--    `data/*.ts` (TravelPackage, Destination, Experience, TravelEvent). La app lo valida al leer y al guardar
--    (lib/catalog/normalize.ts).
-- ============================================================================
create table if not exists catalog_items (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('packages', 'destinations', 'experiences', 'events')),
  slug text not null check (char_length(slug) <= 60 and slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  -- draft = no publicado (oculto en el sitio) · published = visible · archived = oculto y fuera de la lista
  -- principal del panel.
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  -- Orden de aparición en el sitio (menor primero).
  sort_order integer not null default 0,
  data jsonb not null check (jsonb_typeof(data) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (kind, slug)
);

comment on table catalog_items is 'Catálogo editable desde /admin (M12). `data` tiene la forma de los tipos de data/*.ts.';

create index if not exists catalog_items_kind_status_idx on catalog_items(kind, status, sort_order);

drop trigger if exists catalog_items_set_updated_at on catalog_items;
create trigger catalog_items_set_updated_at
  before update on catalog_items
  for each row
  execute function travel_quotes_set_updated_at();

-- ============================================================================
-- 2. RLS: el público solo puede LEER lo publicado. Nadie puede escribir con la clave anónima: el panel escribe
--    desde el servidor con la clave service_role, después de comprobar que quien lo pide es admin.
-- ============================================================================
alter table catalog_items enable row level security;

drop policy if exists "Cualquiera puede leer el catálogo publicado" on catalog_items;
create policy "Cualquiera puede leer el catálogo publicado"
  on catalog_items
  for select
  to anon, authenticated
  using (status = 'published');

-- ============================================================================
-- 3. Semilla: el catálogo de demostración de `data/*.ts` (generado desde esos archivos, no copiado a mano).
